:root {
  --ink: #111827;
  --muted: #667085;
  --line: #d9e0e7;
  --soft: #f5f7fa;
  --accent: #2563eb;
  --accent-dark: #1e3a8a;
}

body {
  margin: 0;
  background: white;
}

.print-actions {
  display: flex;
  justify-content: flex-end;
  margin: 0 0 12px;
}

#printBtn {
  background: #111827;
  color: white;
  border: 0;
  padding: 10px 16px;
  font-weight: 700;
  cursor: pointer;
}

.doc {
  font-family: Arial, sans-serif;
  color: var(--ink);
  background: white;
  padding: 0 28px 28px;
  width: 100%;
  box-sizing: border-box;
}

.topbar {
  height: 8px;
  background: linear-gradient(90deg, var(--accent-dark), var(--accent), #0f766e);
  margin: 0 -28px 24px;
}

.hero {
  display: flex;
  justify-content: space-between;
  gap: 28px;
  align-items: flex-start;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 16px;
}

.logo {
  width: 84px;
  max-height: 72px;
  object-fit: contain;
  display: none;
}

.logo-fallback {
  width: 78px;
  height: 64px;
  background: var(--ink);
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 800;
}

.company-name {
  font-size: 24px;
  font-weight: 800;
  line-height: 1.1;
}

.company-legal {
  margin-top: 5px;
  color: var(--muted);
  font-size: 13px;
}

.doc-card {
  min-width: 280px;
  text-align: right;
}

.badge {
  display: inline-block;
  background: #eff6ff;
  color: var(--accent-dark);
  border: 1px solid #bfdbfe;
  font-size: 11px;
  font-weight: 800;
  padding: 5px 9px;
  text-transform: uppercase;
}

.doc-card h1 {
  margin: 10px 0 4px;
  font-size: 28px;
}

.doc-number {
  font-size: 18px;
  font-weight: 800;
}

.status {
  margin-top: 8px;
  display: inline-block;
  border: 1px solid var(--line);
  padding: 5px 9px;
  font-size: 12px;
  font-weight: 700;
}

.qr-box {
  margin-top: 12px;
  margin-left: auto;
  width: 104px;
  text-align: center;
}

.qr {
  width: 92px;
  height: 92px;
  border: 1px solid var(--line);
  background: white;
  image-rendering: pixelated;
}

.qr-label {
  margin-top: 4px;
  font-size: 9px;
  color: var(--muted);
  word-break: break-all;
}

.company-strip,
.meta-grid {
  display: grid;
  gap: 10px;
  margin: 18px 0;
}

.company-strip {
  grid-template-columns: 1.4fr 0.8fr 1fr 0.8fr;
  background: var(--soft);
  border: 1px solid var(--line);
  padding: 12px;
}

.meta-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.company-strip span,
.meta span,
.summary span {
  display: block;
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  margin-bottom: 5px;
}

.company-strip b,
.meta b {
  display: block;
  font-size: 13px;
  line-height: 1.25;
  word-break: break-word;
}

.meta {
  border: 1px solid var(--line);
  padding: 12px;
}

.flow {
  display: grid;
  grid-template-columns: 1fr 32px 1fr 32px 1fr 32px 1fr;
  gap: 8px;
  align-items: center;
  margin: 14px 0 18px;
}

.flow-step {
  border: 1px solid var(--line);
  background: var(--soft);
  padding: 9px;
  text-align: center;
  font-size: 12px;
  font-weight: 800;
}

.flow-line {
  height: 2px;
  background: var(--line);
}

.items-card {
  border: 1px solid var(--line);
}

.section-title {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--ink);
  color: white;
  padding: 11px 12px;
}

.section-title h2 {
  margin: 0;
  font-size: 15px;
}

.section-title span {
  font-size: 12px;
  color: #d1d5db;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  background: #eef2f6;
  color: #344054;
  font-size: 11px;
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid var(--line);
}

td {
  border-bottom: 1px solid #edf1f5;
  padding: 9px 8px;
  font-size: 12px;
  vertical-align: top;
}

tbody tr:nth-child(even) {
  background: #fbfcfd;
}

.product-code {
  font-weight: 800;
}

.product-name {
  color: var(--muted);
  font-size: 11px;
  margin-top: 2px;
}

.right {
  text-align: right;
}

.bottom {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 18px;
  margin-top: 18px;
  align-items: start;
}

.summary {
  border: 1px solid var(--line);
}

.summary div {
  display: flex;
  justify-content: space-between;
  padding: 11px 12px;
  border-bottom: 1px solid var(--line);
}

.summary div:last-child {
  border-bottom: 0;
  background: var(--soft);
}

.note {
  border: 1px solid var(--line);
  padding: 12px;
  font-size: 12px;
  min-height: 72px;
  display: none;
}

.signatures {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 54px;
  margin-top: 58px;
}

.signatures span {
  display: block;
  border-top: 1px solid var(--ink);
  margin-bottom: 8px;
}

.signatures b {
  display: block;
  text-align: center;
  font-size: 12px;
}

@media print {
  .print-actions {
    display: none;
  }
  .doc {
    padding: 0 18px 18px;
  }
  .topbar {
    margin-left: -18px;
    margin-right: -18px;
  }
}

