import QRCode from "https://esm.sh/qrcode@1.5.3";
function val(value) {
  return String(value ?? "");
}
function money(value) {
  return Number(value || 0).toFixed(2);
}
function qty(value) {
  return Number(value || 0).toFixed(4);
}
function initials(name) {
  return val(name || "AX").split(" ").filter(Boolean).slice(0, 2).map(part => part[0]).join("").toUpperCase();
}
function bindPrintButton() {
  const btn = document.getElementById("printBtn");
  if (!btn) return;
  btn.onclick = function () {
    window.print();
  };
}
function qrPayload(h) {
  return ["AXON:DOCUMENT", "TYPE=TRANSFER_REQUEST", `ID=${h.documentId || ""}`, `NUMBER=${h.documentNumber || ""}`, `DATE=${h.documentDate || ""}`, `STATUS=${h.status || ""}`, `FROM=${h.sourceWarehouseCode || ""}`, `TO=${h.destinationWarehouseCode || ""}`, `TOTAL=${h.totalAmount || ""}`].join("|");
}
async function setQr(h) {
  const qr = document.getElementById("qrCode");
  const label = document.getElementById("qrLabel");
  if (!qr) return;
  qr.src = await QRCode.toDataURL(qrPayload(h), {
    margin: 1,
    width: 180,
    errorCorrectionLevel: "M"
  });
  label.innerText = h.documentNumber || "";
}
function markFlow(status) {
  const steps = Array.from(document.querySelectorAll(".flow-step"));
  const order = ["DRAFT", "PICKED", "SHIPPED", "RECEIVED"];
  const current = status === "REQUESTED" ? "DRAFT" : status;
  const activeIndex = Math.max(0, order.indexOf(current));
  steps.forEach((step, index) => {
    if (index <= activeIndex) {
      step.style.background = "#eff6ff";
      step.style.borderColor = "#2563eb";
      step.style.color = "#1e3a8a";
    }
  });
}
async function render(model) {
  const h = model.header || {};
  const items = model.items || [];
  const companyDisplay = h.companyName || "";
  document.getElementById("companyName").innerText = companyDisplay;
  document.getElementById("companyLegal").innerText = "Warehouse transfer request";
  document.getElementById("companyAddress").innerText = [h.companyAddressLine1, h.companyPostalCode, h.companyCity].filter(Boolean).join(", ") || "-";
  document.getElementById("companyTax").innerText = h.companyTaxNumber || "-";
  document.getElementById("companyContact").innerText = [h.companyEmail, h.companyPhone].filter(Boolean).join(" | ") || "-";
  const logo = document.getElementById("logo");
  const fallback = document.getElementById("logoFallback");
  if (h.companyLogoPath) {
    logo.src = h.companyLogoPath;
    logo.style.display = "block";
    fallback.style.display = "none";
  } else {
    logo.style.display = "none";
    fallback.style.display = "flex";
    fallback.innerText = initials(companyDisplay);
  }
  document.getElementById("documentNumber").innerText = h.documentNumber || "";
  document.getElementById("status").innerText = h.status || "";
  document.getElementById("documentDate").innerText = h.documentDate || "";
  document.getElementById("issueTime").innerText = h.issueTime || h.createdAt || "";
  document.getElementById("createdBy").innerText = model.username || h.createdBy || "";
  document.getElementById("sourceWarehouse").innerText = `${h.sourceWarehouseCode || ""} - ${h.sourceWarehouseName || ""}`.trim() || "-";
  document.getElementById("destinationWarehouse").innerText = `${h.destinationWarehouseCode || ""} - ${h.destinationWarehouseName || ""}`.trim() || "-";
  let totalQty = 0;
  let totalValue = 0;
  document.getElementById("itemsBody").innerHTML = items.map(row => {
    totalQty += Number(row.quantity || 0);
    totalValue += Number(row.lineTotal || 0);
    return `
      <tr>
        <td>${val(row.lineNo)}</td>
        <td>
          <div class="product-code">${val(row.productCode)}</div>
          <div class="product-name">${val(row.productName)}${row.barcode ? " | " + val(row.barcode) : ""}</div>
        </td>
        <td>${val(row.description || row.productName)}</td>
        <td class="right">${qty(row.quantity)}</td>
        <td>${val(row.unitCode)}</td>
        <td class="right">${money(row.unitCost)}</td>
        <td class="right">${money(row.lineTotal)}</td>
        <td>${val(row.note)}</td>
      </tr>
    `;
  }).join("");
  document.getElementById("itemCount").innerText = `${items.length} line${items.length === 1 ? "" : "s"}`;
  document.getElementById("totalQty").innerText = qty(totalQty);
  document.getElementById("totalValue").innerText = money(totalValue);
  const noteBox = document.getElementById("noteBox");
  if (h.note) {
    noteBox.style.display = "block";
    noteBox.innerText = `Note: ${h.note}`;
  } else {
    noteBox.style.display = "none";
  }
  markFlow(h.status || "DRAFT");
  await setQr(h);
  bindPrintButton();
}
appsmith.onReady(() => {
  render(appsmith.model || {});
  bindPrintButton();
});
appsmith.onModelChange(model => {
  render(model || {});
});

